-- Generated by scripts/gen_mvp_weeks.py — Project Physics week inputs (the app is the packet).
-- Idempotent: blocks with ids starting <prefix>d / <prefix>- are stripped, then re-appended.

update public.lessons set content_blocks = jsonb_set(content_blocks, '{blocks}',
  (select coalesce(jsonb_agg(b order by o), '[]'::jsonb) from jsonb_array_elements(content_blocks->'blocks') with ordinality as x(b,o)
     where (b->>'id') not like 'w00d%' and (b->>'id') not like 'w00-%')
  || $$[{"id": "w00d2", "type": "callout", "variant": "tip", "title": "Day 2 · The detector · first touch · Día 2 · El detector · primer contacto", "markdown": "**HANDS · MANOS (25 min) — first, always.** Vernier motion detector on the table. One at a time: walk toward it slowly, away fast, stop. Watch the trace before anyone explains it. · Detector de movimiento Vernier en la mesa. Uno a la vez: camina hacia él despacio, aléjate rápido, detente. Mira la traza antes de que alguien la explique.\n\nThen **RECORD · REGISTRA (25)** → **TALK · HABLA (25, pairs, either language · en parejas, en cualquier idioma)** → **WRITE · ESCRIBE (25, the frame below)**. Every segment ends with something saved here. · Cada segmento termina con algo guardado aquí."}, {"id": "w00d2-trace", "type": "sketch", "capture": true, "targetId": "pp.w00.predict-lock", "xp": 5, "instruction": "RECORD · Sketch what the screen showed for YOUR walk. Label where you walked toward, away, and stopped — in either language. · REGISTRA · Dibuja lo que mostró la pantalla en TU caminata. Marca dónde caminaste hacia, lejos y parado — en cualquier idioma.", "prompts": ["One line for the whole walk · Una línea para toda la caminata", "Label toward / away / stopped · Marca hacia / lejos / parado", "Mark where you were fastest · Marca dónde ibas más rápido"], "grid": true, "xLabel": "time · tiempo (s)", "yLabel": "position · posición (m)", "sei": {"prompt_l1": {"es": "REGISTRA · Dibuja lo que mostró la pantalla en TU caminata. Marca dónde caminaste hacia, lejos y parado — en cualquier idioma."}, "labelBank": ["toward · hacia", "away · lejos", "stopped · parado", "fast · rápido", "slow · lento", "start · inicio"], "modes": ["sketch"]}}, {"id": "w00d2-talk", "type": "callout", "variant": "note", "title": "Talk · Habla — 60 seconds each, then swap · 60 segundos cada uno, luego cambien", "markdown": "**Ask your partner · Pregúntale a tu pareja:** When the line went UP, which way were you walking? How do you know? · Cuando la línea SUBIÓ, ¿hacia dónde caminabas? ¿Cómo lo sabes?\n\nSpanish is allowed. The bridge student translates the physics, not the answer. · Se permite español. El «puente» traduce la física, no la respuesta."}, {"id": "w00d2-write", "type": "sentence_frame", "capture": true, "targetId": "pp.w00.predict-lock", "xp": 5, "frame": "When I walked ___, the line went ___. When I stopped, the line was ___.", "wordBank": ["toward · hacia", "away · lejos", "up · sube", "down · baja", "flat · plana", "steep · empinada"], "frames": [{"level": 1, "text": "When I walked [toward / away], the line went [up / down]. Stopped = [flat].", "text_l1": {"es": "Cuando caminé [hacia / lejos], la línea [subió / bajó]. Parado = [plana]."}}, {"level": 2, "text": "When I walked ___, the line went ___ because ___.", "text_l1": {"es": "Cuando caminé ___, la línea ___ porque ___."}}, {"level": 3, "text": "The trace showed ___", "text_l1": {"es": "La traza mostró ___"}}], "sei": {"prompt_l1": {"es": "ESCRIBE · lo que te dijo la traza"}, "talkFirst": true, "visual": {"src": "/images/sei/flat-section.svg", "alt": "A position-time graph with a rising, a flat and a falling section."}, "modes": ["text"]}, "note": "WRITE · what the trace told you"}, {"id": "w00d2-rate", "type": "self_assessment", "capture": true, "targetIds": ["pp.w00.predict-lock"], "note": "RATE YOURSELF · EVALÚATE — 1 Not yet · 2 Almost · 3 Got it, on each target you worked on today. Opens after the exit ticket on lobby days (MC-6)."}, {"id": "w00d3", "type": "callout", "variant": "tip", "title": "Day 3 · Teams, roles, the timeline · Día 3 · Equipos, roles, la línea de tiempo", "markdown": "**HANDS · MANOS (25 min) — first, always.** Groups of three with one bridge. Roles: hands · recorder · reporter — they rotate every block. Build something in 10 minutes from what is on the table, then open your first timeline entry. · Grupos de tres con un «puente». Roles: manos · registrador · reportero — rotan cada bloque. Construyan algo en 10 minutos con lo que hay en la mesa, luego abran su primera entrada de la línea de tiempo.\n\nThen **RECORD · REGISTRA (25)** → **TALK · HABLA (25, pairs, either language · en parejas, en cualquier idioma)** → **WRITE · ESCRIBE (25, the frame below)**. Every segment ends with something saved here. · Cada segmento termina con algo guardado aquí."}, {"id": "w00d3-timeline", "type": "observation", "capture": true, "targetId": "pp.w00.timeline", "xp": 5, "patternPrompt": "TIMELINE ENTRY #1 · PLANNED — what did your team plan to do this block?", "interpretPrompt": "ACTUAL — what actually happened, and WHY the difference?", "patternFrame": "We planned ___. What actually happened: ___. The gap is because ___.", "comparatives": ["we planned · planeamos", "we actually · en realidad", "because · porque", "ran out of time · faltó tiempo", "it broke · se rompió", "it worked · funcionó"], "sei": {"prompt_l1": {"es": "ENTRADA #1 DE LA LÍNEA DE TIEMPO · PLANEADO — ¿qué planeó hacer tu equipo en este bloque? · REAL — ¿qué pasó de verdad, y POR QUÉ la diferencia?"}, "talkFirst": true, "frames": [{"level": 1, "text": "We planned ___. Actually ___.", "text_l1": {"es": "Planeamos ___. En realidad ___."}}, {"level": 2, "text": "We planned ___. Actually ___. The gap is because ___.", "text_l1": {"es": "Planeamos ___. En realidad ___. La diferencia es porque ___."}}, {"level": 3, "text": "Planned / actual / why: ___", "text_l1": {"es": "Planeado / real / por qué: ___"}}], "visual": {"src": "/images/sei/timeline-entry.svg", "alt": "A timeline card with three boxes: planned, actual, why the gap."}, "modes": ["text", "sketch"]}}, {"id": "w00d3-talk", "type": "callout", "variant": "note", "title": "Talk · Habla — 60 seconds each, then swap · 60 segundos cada uno, luego cambien", "markdown": "**Ask your partner · Pregúntale a tu pareja:** What is one thing your team planned that did NOT happen? Why? · ¿Qué cosa planeó tu equipo que NO pasó? ¿Por qué?\n\nSpanish is allowed. The bridge student translates the physics, not the answer. · Se permite español. El «puente» traduce la física, no la respuesta."}, {"id": "w00d3-rate", "type": "self_assessment", "capture": true, "targetIds": ["pp.w00.timeline"], "note": "RATE YOURSELF · EVALÚATE — 1 Not yet · 2 Almost · 3 Got it, on each target you worked on today. Opens after the exit ticket on lobby days (MC-6)."}, {"id": "w00d4", "type": "callout", "variant": "tip", "title": "Day 4 · Paper tower · predict before you test · Día 4 · Torre de papel · predice antes de probar", "markdown": "**HANDS · MANOS (25 min) — first, always.** Twenty minutes, 10 sheets of paper, 30 cm of tape. Before you build: LOCK a prediction of the height. The prediction is graded for the reasoning, never for being right. · Veinte minutos, 10 hojas de papel, 30 cm de cinta. Antes de construir: FIJA una predicción de la altura. La predicción se califica por el razonamiento, nunca por acertar.\n\nThen **RECORD · REGISTRA (25)** → **TALK · HABLA (25, pairs, either language · en parejas, en cualquier idioma)** → **WRITE · ESCRIBE (25, the frame below)**. Every segment ends with something saved here. · Cada segmento termina con algo guardado aquí."}, {"id": "w00d4-predict", "type": "sentence_frame", "capture": true, "targetId": "pp.w00.predict-lock", "xp": 5, "frame": "I predict our tower will be ___ cm tall, because ___. Evidence that would prove me wrong: ___.", "wordBank": ["taller · más alta", "shorter · más baja", "wide base · base ancha", "folds · dobleces", "tape · cinta", "because · porque"], "frames": [{"level": 1, "text": "I predict ___ cm.", "text_l1": {"es": "Predigo ___ cm."}}, {"level": 2, "text": "I predict ___ cm because ___.", "text_l1": {"es": "Predigo ___ cm porque ___."}}, {"level": 3, "text": "I predict ___ cm because ___. I would be wrong if ___.", "text_l1": {"es": "Predigo ___ cm porque ___. Estaría equivocado si ___."}}], "sei": {"prompt_l1": {"es": "PREDICE (fijada) · antes de que alguien toque el papel"}, "talkFirst": true, "visual": {"src": "/images/sei/2026-xj-approach.svg", "alt": "Earth and the approaching object 2026-XJ."}, "modes": ["text"]}, "note": "PREDICT (locked) · before anyone touches the paper", "gate": true}, {"id": "w00d4-data", "type": "data_table", "capture": true, "targetId": "pp.w00.predict-lock", "xp": 5, "columns": ["Predicted height (cm) · Predicción", "Actual height (cm) · Real", "Gap (cm) · Diferencia"], "rows": 1, "plot": false, "patternPrompt": "Was your prediction high or low? By how much? · ¿Tu predicción fue alta o baja? ¿Por cuánto?", "sei": {"prompt_l1": {"es": "¿Tu predicción fue alta o baja? ¿Por cuánto?"}, "talkFirst": false, "modes": ["text"]}}, {"id": "w00d4-talk", "type": "callout", "variant": "note", "title": "Talk · Habla — 60 seconds each, then swap · 60 segundos cada uno, luego cambien", "markdown": "**Ask your partner · Pregúntale a tu pareja:** Whose tower beat its prediction? What did they do that you did not? · ¿Qué torre superó su predicción? ¿Qué hicieron que tú no?\n\nSpanish is allowed. The bridge student translates the physics, not the answer. · Se permite español. El «puente» traduce la física, no la respuesta."}, {"id": "w00d4-gap", "type": "sentence_frame", "capture": true, "targetId": "pp.w00.predict-lock", "xp": 5, "frame": "We predicted ___ cm. Our tower was ___ cm. The gap is because ___.", "wordBank": ["fell over · se cayó", "base · base", "ran out of tape · se acabó la cinta", "stronger fold · doblez más fuerte", "higher than · más alta que", "lower than · más baja que"], "frames": [{"level": 1, "text": "Predicted ___ cm. Actual ___ cm. [Higher / lower].", "text_l1": {"es": "Predicción ___ cm. Real ___ cm. [Más alta / más baja]."}}, {"level": 2, "text": "We predicted ___ cm and got ___ cm. The gap is because ___.", "text_l1": {"es": "Predijimos ___ cm y obtuvimos ___ cm. La diferencia es porque ___."}}, {"level": 3, "text": "Gap: ___ — because ___", "text_l1": {"es": "Diferencia: ___ — porque ___"}}], "sei": {"prompt_l1": {"es": "ESCRIBE · la diferencia"}, "talkFirst": true, "visual": {"src": "/images/sei/timeline-entry.svg", "alt": "Planned, actual, why the gap."}, "modes": ["text"]}, "note": "WRITE · the gap"}, {"id": "w00d4-timeline", "type": "observation", "capture": true, "targetId": "pp.w00.timeline", "xp": 5, "patternPrompt": "TIMELINE ENTRY #2 · PLANNED — what did your team plan to do this block?", "interpretPrompt": "ACTUAL — what actually happened, and WHY the difference?", "patternFrame": "We planned ___. What actually happened: ___. The gap is because ___.", "comparatives": ["we planned · planeamos", "we actually · en realidad", "because · porque", "ran out of time · faltó tiempo", "it broke · se rompió", "it worked · funcionó"], "sei": {"prompt_l1": {"es": "ENTRADA #2 DE LA LÍNEA DE TIEMPO · PLANEADO — ¿qué planeó hacer tu equipo en este bloque? · REAL — ¿qué pasó de verdad, y POR QUÉ la diferencia?"}, "talkFirst": true, "frames": [{"level": 1, "text": "We planned ___. Actually ___.", "text_l1": {"es": "Planeamos ___. En realidad ___."}}, {"level": 2, "text": "We planned ___. Actually ___. The gap is because ___.", "text_l1": {"es": "Planeamos ___. En realidad ___. La diferencia es porque ___."}}, {"level": 3, "text": "Planned / actual / why: ___", "text_l1": {"es": "Planeado / real / por qué: ___"}}], "visual": {"src": "/images/sei/timeline-entry.svg", "alt": "A timeline card with three boxes: planned, actual, why the gap."}, "modes": ["text", "sketch"]}}, {"id": "w00-exit", "type": "exit_ticket", "capture": true, "targetId": "pp.w00.predict-lock", "xp": 5, "talkFirst": true, "prompt": "EXIT · Week 0 · What will you do differently on the next build — and what prediction will you lock first?", "frame": "Next build I will ___. First I will predict ___.", "sei": {"prompt_l1": {"es": "SALIDA · Semana 0 · ¿Qué harás diferente en la próxima construcción — y qué predicción fijarás primero?"}, "talkFirst": true, "frames": [{"level": 1, "text": "Next build I will [test first / plan the base / write the number].", "text_l1": {"es": "La próxima vez voy a [probar primero / planear la base / escribir el número]."}}, {"level": 2, "text": "Next build I will ___ because ___. First I will predict ___.", "text_l1": {"es": "La próxima vez haré ___ porque ___. Primero predeciré ___."}}, {"level": 3, "text": "Next time: ___", "text_l1": {"es": "La próxima vez: ___"}}], "wordBank": ["plan · planear", "test · probar", "measure · medir", "predict · predecir", "because · porque"], "visual": {"src": "/images/sei/2026-xj-approach.svg", "alt": "Earth and the approaching object 2026-XJ."}, "modes": ["text", "sketch"]}}, {"id": "w00d4-rate", "type": "self_assessment", "capture": true, "targetIds": ["pp.w00.predict-lock", "pp.w00.timeline"], "note": "RATE YOURSELF · EVALÚATE — 1 Not yet · 2 Almost · 3 Got it, on each target you worked on today. Opens after the exit ticket on lobby days (MC-6)."}]$$::jsonb), updated_at = now()
where slug = 'pp-w00';
select public.split_mvp_week('pp-w00');  -- one lesson per day for students (2026-09-04)

update public.lessons set content_blocks = jsonb_set(content_blocks, '{blocks}',
  (select coalesce(jsonb_agg(b order by o), '[]'::jsonb) from jsonb_array_elements(content_blocks->'blocks') with ordinality as x(b,o)
     where (b->>'id') not like 'w01d%' and (b->>'id') not like 'w01-%')
  || $$[{"id": "w01d1", "type": "callout", "variant": "tip", "title": "Day 1 · Walk the graph · Día 1 · Camina la gráfica", "markdown": "**HANDS · MANOS (25 min) — first, always.** Motion detector + the graph-matching screen. Walk to match three graphs. Then the reverse: sketch the graph of a walk BEFORE the screen draws it. · Detector de movimiento + pantalla de emparejar gráficas. Camina para igualar tres gráficas. Luego al revés: dibuja la gráfica de una caminata ANTES de que la pantalla la dibuje.\n\nThen **RECORD · REGISTRA (25)** → **TALK · HABLA (25, pairs, either language · en parejas, en cualquier idioma)** → **WRITE · ESCRIBE (25, the frame below)**. Every segment ends with something saved here. · Cada segmento termina con algo guardado aquí."}, {"id": "w01d1-predict", "type": "sketch", "capture": true, "targetId": "pp.w01.sketch-first", "xp": 5, "instruction": "PREDICT · Sketch the position–time graph of this walk BEFORE you do it: stand 1 m away, walk away slowly for 3 s, stop for 2 s, walk back fast. · PREDICE · Dibuja la gráfica posición–tiempo de esta caminata ANTES de hacerla: párate a 1 m, aléjate despacio 3 s, detente 2 s, regresa rápido.", "prompts": ["Start 1 m from the detector · Empieza a 1 m", "Away slowly = gentle up · Lejos despacio = sube suave", "Stop = flat · Parado = plana", "Back fast = steep down · Regresa rápido = baja empinada"], "grid": true, "xLabel": "time · tiempo (s)", "yLabel": "position · posición (m)", "sei": {"prompt_l1": {"es": "PREDICE · Dibuja la gráfica posición–tiempo de esta caminata ANTES de hacerla: párate a 1 m, aléjate despacio 3 s, detente 2 s, regresa rápido."}, "labelBank": ["away · lejos", "toward · hacia", "stopped · parado", "slow · lento", "fast · rápido", "steep · empinada"], "modes": ["sketch"]}}, {"id": "w01d1-scores", "type": "data_table", "capture": true, "targetId": "pp.w01.read-graph", "xp": 5, "columns": ["Graph · Gráfica", "Match score (%) · Puntaje", "What I fixed · Qué corregí"], "rows": 3, "plot": false, "patternPrompt": "Which part of a graph was hardest to walk? Why? · ¿Qué parte de la gráfica fue más difícil de caminar? ¿Por qué?", "sei": {"prompt_l1": {"es": "¿Qué parte de la gráfica fue más difícil de caminar? ¿Por qué?"}, "talkFirst": false, "modes": ["text"]}}, {"id": "w01d1-talk", "type": "callout", "variant": "note", "title": "Talk · Habla — 60 seconds each, then swap · 60 segundos cada uno, luego cambien", "markdown": "**Ask your partner · Pregúntale a tu pareja:** Show your partner your sketch and the screen. Where do they disagree, and who was right? · Muestra a tu pareja tu dibujo y la pantalla. ¿Dónde no coinciden, y quién tenía razón?\n\nSpanish is allowed. The bridge student translates the physics, not the answer. · Se permite español. El «puente» traduce la física, no la respuesta."}, {"id": "w01d1-write", "type": "sentence_frame", "capture": true, "targetId": "pp.w01.read-graph", "xp": 5, "frame": "When the line goes UP, I am walking ___. When it is FLAT, I am ___. When it is STEEP, I am going ___.", "wordBank": ["away · lejos", "toward · hacia", "stopped · parado", "faster · más rápido", "slower · más lento", "steady · constante"], "frames": [{"level": 1, "text": "Up = [away / toward]. Flat = [stopped / steady]. Steep = [faster / slower].", "text_l1": {"es": "Sube = [lejos / hacia]. Plana = [parado / constante]. Empinada = [más rápido / más lento]."}}, {"level": 2, "text": "When the line goes up I am walking ___; flat means ___; steep means ___.", "text_l1": {"es": "Cuando la línea sube camino ___; plana significa ___; empinada significa ___."}}, {"level": 3, "text": "In my words: ___", "text_l1": {"es": "Con mis palabras: ___"}}], "sei": {"prompt_l1": {"es": "ESCRIBE · lee la gráfica"}, "talkFirst": true, "visual": {"src": "/images/sei/flat-section.svg", "alt": "A position-time graph with a rising, a flat and a falling section."}, "modes": ["text"]}, "note": "WRITE · read the graph"}, {"id": "w01d1-rate", "type": "self_assessment", "capture": true, "targetIds": ["pp.w01.sketch-first", "pp.w01.read-graph"], "note": "RATE YOURSELF · EVALÚATE — 1 Not yet · 2 Almost · 3 Got it, on each target you worked on today. Opens after the exit ticket on lobby days (MC-6)."}, {"id": "w01d2", "type": "callout", "variant": "tip", "title": "Day 2 · Sims that CHECK, never draw first · Día 2 · Sims que COMPRUEBAN, nunca dibujan primero", "markdown": "**HANDS · MANOS (25 min) — first, always.** Two sims. Rule: write your predicted graph shape in the table, THEN run the sim. Fix your prediction in the third column — the fix is the learning. · Dos sims. Regla: escribe la forma de la gráfica que predices en la tabla, LUEGO corre el sim. Corrige tu predicción en la tercera columna — la corrección es el aprendizaje.\n\nThen **RECORD · REGISTRA (25)** → **TALK · HABLA (25, pairs, either language · en parejas, en cualquier idioma)** → **WRITE · ESCRIBE (25, the frame below)**. Every segment ends with something saved here. · Cada segmento termina con algo guardado aquí."}, {"id": "w01d2-sim1", "type": "sim_embed", "simulationSlug": "constant-velocity"}, {"id": "w01d2-check", "type": "data_table", "capture": true, "targetId": "pp.w01.sketch-first", "xp": 5, "columns": ["Motion I set · Movimiento que puse", "Predicted x–t shape · Forma predicha", "What the sim drew · Lo que dibujó", "My fix · Mi corrección"], "rows": 3, "plot": false, "patternPrompt": "What did you predict wrong most often — the direction, the steepness, or the flat parts? · ¿Qué predijiste mal más seguido — la dirección, la inclinación o las partes planas?", "sei": {"prompt_l1": {"es": "¿Qué predijiste mal más seguido — la dirección, la inclinación o las partes planas?"}, "talkFirst": false, "modes": ["text"]}}, {"id": "w01d2-sim2", "type": "sim_embed", "simulationSlug": "uniformly-accelerated-motion"}, {"id": "w01d2-vt", "type": "question", "capture": true, "targetId": "pp.w01.a-from-slope", "xp": 5, "question": {"prompt": "On a VELOCITY–time graph the line is flat, above zero. What is the object doing?", "options": [{"id": "steady", "icon": "➡", "text": "Moving at a steady speed — the velocity is not changing", "text_l1": {"es": "Moviéndose a rapidez constante — la velocidad no cambia"}, "feedback": "Yes. Flat on a v–t graph means constant velocity. (Flat on an x–t graph meant stopped — different graph, different meaning.) · Sí: plana en v–t es velocidad constante."}, {"id": "stopped", "icon": "🛑", "text": "Stopped", "text_l1": {"es": "Detenido"}, "feedback": "That is what flat means on a POSITION graph. Here the flat line is above zero — the velocity is a steady non-zero number. · Eso es lo que significa plana en una gráfica de POSICIÓN. Aquí la línea está arriba de cero."}, {"id": "faster", "icon": "📈", "text": "Speeding up", "text_l1": {"es": "Acelerando"}, "feedback": "Speeding up would be a line going UP on v–t. Flat means the speed stays the same. · Acelerar sería una línea que SUBE en v–t."}], "correctOptionId": "steady", "explain": "Say the rule for x–t and the rule for v–t in one sentence each. · Di la regla para x–t y la regla para v–t, una oración cada una."}, "sei": {"prompt_l1": {"es": "En una gráfica VELOCIDAD–tiempo la línea es plana, arriba de cero. ¿Qué hace el objeto?"}, "talkFirst": true, "frames": [{"level": 1, "text": "Flat on x–t = [stopped]. Flat on v–t = [steady speed].", "text_l1": {"es": "Plana en x–t = [parado]. Plana en v–t = [rapidez constante]."}}, {"level": 2, "text": "On x–t, flat means ___. On v–t, flat means ___, because ___.", "text_l1": {"es": "En x–t, plana significa ___. En v–t, plana significa ___, porque ___."}}], "visual": {"src": "/images/sei/flat-section.svg", "alt": "A position-time graph with a rising, a flat and a falling section."}, "modes": ["choice"]}, "gate": true}, {"id": "w01d2-talk", "type": "callout", "variant": "note", "title": "Talk · Habla — 60 seconds each, then swap · 60 segundos cada uno, luego cambien", "markdown": "**Ask your partner · Pregúntale a tu pareja:** Which graph is which? Explain to your partner how you tell an x–t graph from a v–t graph without reading the label. · ¿Cuál gráfica es cuál? Explícale a tu pareja cómo distingues una gráfica x–t de una v–t sin leer la etiqueta.\n\nSpanish is allowed. The bridge student translates the physics, not the answer. · Se permite español. El «puente» traduce la física, no la respuesta."}, {"id": "w01d2-rate", "type": "self_assessment", "capture": true, "targetIds": ["pp.w01.sketch-first", "pp.w01.a-from-slope"], "note": "RATE YOURSELF · EVALÚATE — 1 Not yet · 2 Almost · 3 Got it, on each target you worked on today. Opens after the exit ticket on lobby days (MC-6)."}, {"id": "w01d3", "type": "callout", "variant": "tip", "title": "Day 3 · A number out of a graph · slope and area · Día 3 · Un número de una gráfica · pendiente y área", "markdown": "**HANDS · MANOS (25 min) — first, always.** Slope calculator first: drag two points on an x–t graph, read the slope, say what it means. Then area under a v–t curve. These are the two moves every build this year will use. · Primero la calculadora de pendiente: arrastra dos puntos en una gráfica x–t, lee la pendiente, di qué significa. Luego el área bajo una curva v–t. Estos son los dos movimientos que usará cada construcción este año.\n\nThen **RECORD · REGISTRA (25)** → **TALK · HABLA (25, pairs, either language · en parejas, en cualquier idioma)** → **WRITE · ESCRIBE (25, the frame below)**. Every segment ends with something saved here. · Cada segmento termina con algo guardado aquí."}, {"id": "w01d3-sim1", "type": "sim_embed", "simulationSlug": "slope-calculator"}, {"id": "w01d3-gewa1", "type": "gewa", "capture": true, "targetId": "pp.w01.v-from-slope", "xp": 5, "prompt": "A cart is at 2.0 m at t = 1.0 s and at 3.0 m at t = 5.0 s. Use the slope of its position–time graph to find its velocity. · Un carrito está en 2.0 m en t = 1.0 s y en 3.0 m en t = 5.0 s. Usa la pendiente de su gráfica posición–tiempo para hallar su velocidad.", "givenHint": "two positions and two times · dos posiciones y dos tiempos", "equationHint": "v = Δx / Δt  (rise over run · elevación sobre avance)", "solveFor": "v", "equationIds": ["avg-velocity", "avg-speed", "displacement", "avg-acceleration"], "sei": {"prompt_l1": {"es": "Halla la velocidad desde la pendiente: v = Δx / Δt."}, "tier2Terms": ["slope"]}}, {"id": "w01d3-sim2", "type": "sim_embed", "simulationSlug": "area-under-curve"}, {"id": "w01d3-gewa2", "type": "gewa", "capture": true, "targetId": "pp.w01.area", "xp": 5, "prompt": "A cart moves at a steady 0.40 m/s for 6.0 s. Use the area under its velocity–time graph to find how far it went. · Un carrito se mueve a 0.40 m/s constantes durante 6.0 s. Usa el área bajo su gráfica velocidad–tiempo para hallar cuánto avanzó.", "givenHint": "a velocity and a time · una velocidad y un tiempo", "equationHint": "Δx = v · Δt  (area of the rectangle · área del rectángulo)", "solveFor": "Δx", "equationIds": ["displacement", "avg-velocity", "avg-speed", "avg-acceleration"], "sei": {"prompt_l1": {"es": "Halla el desplazamiento desde el área: Δx = v · Δt."}, "tier2Terms": ["area"]}}, {"id": "w01d3-talk", "type": "callout", "variant": "note", "title": "Talk · Habla — 60 seconds each, then swap · 60 segundos cada uno, luego cambien", "markdown": "**Ask your partner · Pregúntale a tu pareja:** Slope or area — which one gives you a velocity, and which one gives you a distance? Why does that make sense? · Pendiente o área — ¿cuál te da una velocidad y cuál una distancia? ¿Por qué tiene sentido?\n\nSpanish is allowed. The bridge student translates the physics, not the answer. · Se permite español. El «puente» traduce la física, no la respuesta."}, {"id": "w01d3-write", "type": "sentence_frame", "capture": true, "targetId": "pp.w01.v-from-slope", "xp": 5, "frame": "The SLOPE of a position–time graph tells me ___. The AREA under a velocity–time graph tells me ___.", "wordBank": ["velocity · velocidad", "how far · cuánto avanzó", "displacement · desplazamiento", "steeper = faster · más empinada = más rápido", "rise over run · elevación sobre avance", "rectangle · rectángulo"], "frames": [{"level": 1, "text": "Slope → [velocity / distance]. Area → [velocity / distance].", "text_l1": {"es": "Pendiente → [velocidad / distancia]. Área → [velocidad / distancia]."}}, {"level": 2, "text": "The slope tells me ___ because ___. The area tells me ___ because ___.", "text_l1": {"es": "La pendiente me dice ___ porque ___. El área me dice ___ porque ___."}}, {"level": 3, "text": "Slope: ___ · Area: ___", "text_l1": {"es": "Pendiente: ___ · Área: ___"}}], "sei": {"prompt_l1": {"es": "ESCRIBE · los dos movimientos, con tus palabras"}, "talkFirst": true, "visual": {"src": "/images/sei/flat-section.svg", "alt": "A position-time graph with a rising, a flat and a falling section."}, "modes": ["text"]}, "note": "WRITE · the two moves, in your own words"}, {"id": "w01d3-rate", "type": "self_assessment", "capture": true, "targetIds": ["pp.w01.v-from-slope", "pp.w01.area"], "note": "RATE YOURSELF · EVALÚATE — 1 Not yet · 2 Almost · 3 Got it, on each target you worked on today. Opens after the exit ticket on lobby days (MC-6)."}, {"id": "w01d4", "type": "callout", "variant": "tip", "title": "Day 4 · A real cart on the track · Día 4 · Un carrito real en la pista", "markdown": "**HANDS · MANOS (25 min) — first, always.** Cart on the track, motion detector at one end. Before every push: sketch the graph you expect. Three runs — slow push, fast push, push then catch. · Carrito en la pista, detector en un extremo. Antes de cada empujón: dibuja la gráfica que esperas. Tres corridas — empujón lento, rápido, empujar y atrapar.\n\nThen **RECORD · REGISTRA (25)** → **TALK · HABLA (25, pairs, either language · en parejas, en cualquier idioma)** → **WRITE · ESCRIBE (25, the frame below)**. Every segment ends with something saved here. · Cada segmento termina con algo guardado aquí."}, {"id": "w01d4-predict", "type": "sketch", "capture": true, "targetId": "pp.w01.sketch-first", "xp": 5, "instruction": "PREDICT · Sketch the position–time graph for run 2 (fast push, cart rolls to the end) BEFORE you push. · PREDICE · Dibuja la gráfica posición–tiempo de la corrida 2 (empujón rápido, el carrito rueda hasta el final) ANTES de empujar.", "prompts": ["Where does it start? · ¿Dónde empieza?", "Steep or gentle? · ¿Empinada o suave?", "Does it slow down? · ¿Frena?"], "grid": true, "xLabel": "time · tiempo (s)", "yLabel": "position · posición (m)", "sei": {"prompt_l1": {"es": "PREDICE · Dibuja la gráfica posición–tiempo de la corrida 2 (empujón rápido, el carrito rueda hasta el final) ANTES de empujar."}, "labelBank": ["start · inicio", "end · final", "steep · empinada", "slowing · frenando", "steady · constante"], "modes": ["sketch"]}}, {"id": "w01d4-data", "type": "data_table", "capture": true, "targetId": "pp.w01.v-from-slope", "xp": 5, "columns": ["Run · Corrida", "Start x (m)", "End x (m)", "Time (s) · Tiempo", "Velocity = Δx/Δt (m/s)"], "rows": 3, "plot": false, "patternPrompt": "Which run had the biggest slope? Does the number agree with what you saw? · ¿Qué corrida tuvo la pendiente más grande? ¿El número coincide con lo que viste?", "sei": {"prompt_l1": {"es": "¿Qué corrida tuvo la pendiente más grande? ¿El número coincide con lo que viste?"}, "talkFirst": false, "modes": ["text"]}}, {"id": "w01d4-compare", "type": "observation", "capture": true, "targetId": "pp.w01.sketch-first", "xp": 5, "patternPrompt": "RECORD · Where did the detector's graph match your sketch, and where did it not?", "interpretPrompt": "FIX · What will you draw differently next time, and why?", "patternFrame": "My sketch matched at ___. It was wrong at ___.", "comparatives": ["start · inicio", "steepness · inclinación", "the end · el final", "slowing down · frenando", "flat · plana", "curve · curva"], "sei": {"prompt_l1": {"es": "REGISTRA · ¿Dónde coincidió la gráfica del detector con tu dibujo, y dónde no? · CORRIGE · ¿Qué dibujarás diferente la próxima vez, y por qué?"}, "talkFirst": true, "frames": [{"level": 1, "text": "Matched: [start / steepness / end]. Wrong: [start / steepness / end].", "text_l1": {"es": "Coincidió: [inicio / inclinación / final]. Mal: [inicio / inclinación / final]."}}, {"level": 2, "text": "My sketch matched at ___ but was wrong at ___ because ___. Next time I will ___.", "text_l1": {"es": "Mi dibujo coincidió en ___ pero falló en ___ porque ___. La próxima vez ___."}}], "visual": {"src": "/images/sei/flat-section.svg", "alt": "A position-time graph with a rising, a flat and a falling section."}, "modes": ["text", "sketch"]}}, {"id": "w01d4-talk", "type": "callout", "variant": "note", "title": "Talk · Habla — 60 seconds each, then swap · 60 segundos cada uno, luego cambien", "markdown": "**Ask your partner · Pregúntale a tu pareja:** The cart slowed down at the end. What did that look like on the graph? What word do we not have yet for that? · El carrito frenó al final. ¿Cómo se vio en la gráfica? ¿Qué palabra nos falta todavía para eso?\n\nSpanish is allowed. The bridge student translates the physics, not the answer. · Se permite español. El «puente» traduce la física, no la respuesta."}, {"id": "w01d4-timeline", "type": "observation", "capture": true, "targetId": "pp.w00.timeline", "xp": 5, "patternPrompt": "TIMELINE ENTRY #3 · PLANNED — what did your team plan to do this block?", "interpretPrompt": "ACTUAL — what actually happened, and WHY the difference?", "patternFrame": "We planned ___. What actually happened: ___. The gap is because ___.", "comparatives": ["we planned · planeamos", "we actually · en realidad", "because · porque", "ran out of time · faltó tiempo", "it broke · se rompió", "it worked · funcionó"], "sei": {"prompt_l1": {"es": "ENTRADA #3 DE LA LÍNEA DE TIEMPO · PLANEADO — ¿qué planeó hacer tu equipo en este bloque? · REAL — ¿qué pasó de verdad, y POR QUÉ la diferencia?"}, "talkFirst": true, "frames": [{"level": 1, "text": "We planned ___. Actually ___.", "text_l1": {"es": "Planeamos ___. En realidad ___."}}, {"level": 2, "text": "We planned ___. Actually ___. The gap is because ___.", "text_l1": {"es": "Planeamos ___. En realidad ___. La diferencia es porque ___."}}, {"level": 3, "text": "Planned / actual / why: ___", "text_l1": {"es": "Planeado / real / por qué: ___"}}], "visual": {"src": "/images/sei/timeline-entry.svg", "alt": "A timeline card with three boxes: planned, actual, why the gap."}, "modes": ["text", "sketch"]}}, {"id": "w01d4-rate", "type": "self_assessment", "capture": true, "targetIds": ["pp.w01.sketch-first", "pp.w01.v-from-slope", "pp.w00.timeline"], "note": "RATE YOURSELF · EVALÚATE — 1 Not yet · 2 Almost · 3 Got it, on each target you worked on today. Opens after the exit ticket on lobby days (MC-6)."}, {"id": "w01d5", "type": "callout", "variant": "tip", "title": "Day 5 · The reasoning artifact · Día 5 · El artefacto de razonamiento", "markdown": "**HANDS · MANOS (25 min) — first, always.** No new hands today. Record 07 is a motion nobody in the shop has seen. Describe it segment by segment, defend every claim from the graph, then draw the graph that WOULD match a motion described in words. · Hoy no hay manos nuevas. El Registro 07 es un movimiento que nadie en el taller ha visto. Descríbelo segmento por segmento, defiende cada afirmación con la gráfica, luego dibuja la gráfica que correspondería a un movimiento descrito con palabras.\n\nThen **RECORD · REGISTRA (25)** → **TALK · HABLA (25, pairs, either language · en parejas, en cualquier idioma)** → **WRITE · ESCRIBE (25, the frame below)**. Every segment ends with something saved here. · Cada segmento termina con algo guardado aquí."}, {"id": "w01d5-fig", "type": "figure", "src": "/images/sei/mystery-xt.svg", "align": "full", "alt": "Position-time graph in four segments: A flat at 1 m for 2 s, B rising to 3 m over 2 s, C flat at 3 m for 2 s, D falling to 0 m over 2 s.", "caption": "Record 07 · four segments A–D · cuatro segmentos A–D"}, {"id": "w01d5-artifact", "type": "observation", "capture": true, "targetId": "pp.w01.read-graph", "xp": 5, "patternPrompt": "ARTIFACT 1 · Describe the motion in Record 07, segment by segment (A, B, C, D): which way, how fast, stopped?", "interpretPrompt": "DEFEND · For ONE segment, say which feature of the graph proves your description (slope? flat? steepness?) and give its velocity as a number.", "patternFrame": "A: ___. B: ___. C: ___. D: ___.", "comparatives": ["stopped · parado", "away · lejos", "toward · hacia", "slope · pendiente", "faster · más rápido", "m/s"], "sei": {"prompt_l1": {"es": "ARTEFACTO 1 · Describe el movimiento del Registro 07, segmento por segmento (A, B, C, D): hacia dónde, qué tan rápido, parado? · DEFIENDE · Para UN segmento, di qué característica de la gráfica prueba tu descripción (¿pendiente? ¿plana? ¿inclinación?) y da su velocidad como número."}, "talkFirst": true, "frames": [{"level": 1, "text": "A: [stopped / away / toward]. B: [stopped / away / toward]. C: ___. D: ___.", "text_l1": {"es": "A: [parado / lejos / hacia]. B: [parado / lejos / hacia]. C: ___. D: ___."}}, {"level": 2, "text": "In segment ___ the object ___ because the slope is ___ (v = ___ m/s).", "text_l1": {"es": "En el segmento ___ el objeto ___ porque la pendiente es ___ (v = ___ m/s)."}}, {"level": 3, "text": "Claim + evidence: ___", "text_l1": {"es": "Afirmación + evidencia: ___"}}], "modes": ["text", "sketch"]}, "lobbyReady": true}, {"id": "w01d5-draw", "type": "sketch", "capture": true, "targetId": "pp.w01.sketch-first", "xp": 5, "instruction": "ARTIFACT 2 · Draw the position–time graph that WOULD match: \"It sat still 2 m away for 2 s, moved away at a steady speed for 4 s, then came back faster than it left.\" · ARTEFACTO 2 · Dibuja la gráfica posición–tiempo que correspondería a: «Se quedó quieto a 2 m durante 2 s, se alejó a rapidez constante 4 s, luego regresó más rápido de lo que se fue».", "prompts": ["Flat first · Primero plana", "Then a steady line up · Luego una línea recta que sube", "Then steeper down · Luego baja más empinada"], "grid": true, "xLabel": "time · tiempo (s)", "yLabel": "position · posición (m)", "sei": {"prompt_l1": {"es": "ARTEFACTO 2 · Dibuja la gráfica posición–tiempo que correspondería a: «Se quedó quieto a 2 m durante 2 s, se alejó a rapidez constante 4 s, luego regresó más rápido de lo que se fue»."}, "labelBank": ["still · quieto", "steady · constante", "faster · más rápido", "away · lejos", "back · regresa"], "modes": ["sketch"]}}, {"id": "w01d5-talk", "type": "callout", "variant": "note", "title": "Talk · Habla — 60 seconds each, then swap · 60 segundos cada uno, luego cambien", "markdown": "**Ask your partner · Pregúntale a tu pareja:** Trade artifacts. Find one claim on your partner's page you could prove wrong from the graph — or say why you cannot. · Intercambien artefactos. Encuentra una afirmación en la página de tu pareja que podrías refutar con la gráfica — o di por qué no puedes.\n\nSpanish is allowed. The bridge student translates the physics, not the answer. · Se permite español. El «puente» traduce la física, no la respuesta."}, {"id": "w01-exit", "type": "exit_ticket", "capture": true, "targetId": "pp.w01.read-graph", "xp": 5, "talkFirst": true, "prompt": "EXIT · Week 1 · One thing about graphs that still confuses me — and one thing I can now do that I could not on Monday.", "frame": "I still get confused by ___. Now I can ___.", "sei": {"prompt_l1": {"es": "SALIDA · Semana 1 · Una cosa de las gráficas que todavía me confunde — y una cosa que ahora puedo hacer y el lunes no."}, "talkFirst": true, "frames": [{"level": 1, "text": "Confused by: [flat / steep / x–t vs v–t]. Now I can: [read / sketch / find slope].", "text_l1": {"es": "Me confunde: [plana / empinada / x–t vs v–t]. Ahora puedo: [leer / dibujar / hallar la pendiente]."}}, {"level": 2, "text": "I still get confused by ___ because ___. Now I can ___.", "text_l1": {"es": "Todavía me confunde ___ porque ___. Ahora puedo ___."}}, {"level": 3, "text": "Still: ___ · Now: ___", "text_l1": {"es": "Todavía: ___ · Ahora: ___"}}], "wordBank": ["slope · pendiente", "area · área", "flat · plana", "steep · empinada", "sketch · dibujar"], "visual": {"src": "/images/sei/mystery-xt.svg", "alt": "A position-time graph in four segments A to D: flat, rising, flat, falling to zero."}, "modes": ["text", "sketch"]}}, {"id": "w01d5-rate", "type": "self_assessment", "capture": true, "targetIds": ["pp.w01.read-graph", "pp.w01.sketch-first"], "note": "RATE YOURSELF · EVALÚATE — 1 Not yet · 2 Almost · 3 Got it, on each target you worked on today. Opens after the exit ticket on lobby days (MC-6)."}]$$::jsonb), updated_at = now()
where slug = 'pp-w01';
select public.split_mvp_week('pp-w01');  -- one lesson per day for students (2026-09-04)

update public.lessons set content_blocks = jsonb_set(content_blocks, '{blocks}',
  (select coalesce(jsonb_agg(b order by o), '[]'::jsonb) from jsonb_array_elements(content_blocks->'blocks') with ordinality as x(b,o)
     where (b->>'id') not like 'w02d%' and (b->>'id') not like 'w02-%')
  || $$[{"id": "w02d1", "type": "callout", "variant": "tip", "title": "Day 1 · Three angles, one cart · Día 1 · Tres angulos, un carrito", "markdown": "**HANDS · MANOS (25 min) — first, always.** Two releases first - the flattest tape mark and the steepest - and nothing written. Then your own three angles, motion detector at the low end, acceleration from the SLOPE of the v-t graph. Last week's move on this week's cart. · Primero dos sueltas - la marca mas plana y la mas empinada - sin escribir nada. Luego sus tres angulos, detector de movimiento abajo, la aceleracion desde la PENDIENTE de la grafica v-t. El movimiento de la semana pasada en el carrito de esta semana.\n\nThen **RECORD · REGISTRA (30)** → **TALK · HABLA (25, pairs, either language · en parejas, en cualquier idioma)** → **WRITE · ESCRIBE (25, the frame below)**. Every segment ends with something saved here. · Cada segmento termina con algo guardado aquí."}, {"id": "w02d1-faster", "type": "question", "capture": true, "targetId": "pp.w02.a-vs-angle", "xp": 5, "question": {"prompt": "The steep ramp and the flat ramp. Is the steep cart just FASTER the whole way, or is it GAINING speed faster?", "options": [{"id": "gaining", "icon": "UP", "text": "It GAINS speed faster - its acceleration is bigger", "text_l1": {"es": "GANA rapidez mas rapido - su aceleracion es mayor"}, "feedback": "Yes. Faster and gaining-speed-faster are two different numbers, and this week measures the second one. / Si. Rapido y ganar-rapidez-mas-rapido son dos numeros distintos."}, {"id": "faster", "icon": "FLAG", "text": "It is just faster, the whole way down", "text_l1": {"es": "Solo va mas rapido, todo el camino"}, "feedback": "It IS faster at the bottom - but that is the RESULT. What made it faster? It gained speed at a bigger rate. / SI va mas rapido al final - pero eso es el RESULTADO."}, {"id": "same", "icon": "EQ", "text": "Both the same", "text_l1": {"es": "Los dos igual"}, "feedback": "Release both and watch again. Same start, different finish - something is different. / Suelta los dos y mira otra vez."}], "correctOptionId": "gaining", "explain": "Speed is where you got to. Acceleration is how fast you got there. This week measures acceleration. · La rapidez es a donde llegaste. La aceleracion es que tan rapido llegaste. Esta semana medimos la aceleracion."}, "sei": {"prompt_l1": {"es": "La rampa empinada y la rampa plana. El carrito empinado solo va MAS RAPIDO todo el tiempo, o GANA rapidez mas rapido?"}, "talkFirst": true, "frames": [{"level": 1, "text": "The steep cart [is faster / gains speed faster].", "text_l1": {"es": "El carrito empinado [va mas rapido / gana rapidez mas rapido]."}}, {"level": 2, "text": "The steep cart ___ because ___.", "text_l1": {"es": "El carrito empinado ___ porque ___."}}], "visual": {"src": "/images/sei/ramp-dilutes-g.svg", "alt": "A cart on a ramp: a red arrow g straight down, a shorter green arrow along the ramp. Steeper means closer to g."}, "modes": ["choice"]}}, {"id": "w02d1-data", "type": "data_table", "capture": true, "targetId": "pp.w02.a-vs-angle", "xp": 5, "columns": ["Tape mark / Marca", "Angle (deg) / Angulo", "a run 1 (m/s2)", "a run 2 (m/s2)", "a run 3 (m/s2)", "Average a / Promedio"], "rows": 3, "plot": true, "patternPrompt": "As the angle got bigger, what happened to the acceleration? Compare your average to g x sin(angle) for that mark. · Cuando el angulo crecio, que paso con la aceleracion? Compara tu promedio con g x sen(angulo) de esa marca.", "sei": {"prompt_l1": {"es": "Cuando el angulo crecio, que paso con la aceleracion? Compara tu promedio con g x sen(angulo) de esa marca."}, "talkFirst": false, "visual": {"src": "/images/sei/ramp-dilutes-g.svg", "alt": "A cart on a ramp: a red arrow g straight down, a shorter green arrow along the ramp. Steeper means closer to g."}, "modes": ["text"]}}, {"id": "w02d1-plot", "type": "sketch", "capture": true, "targetId": "pp.w02.a-vs-angle", "xp": 5, "instruction": "PLOT BY HAND - put your three points on the axes before any screen draws them. Angle across, acceleration up. · GRAFICA A MANO - pon tus tres puntos en los ejes antes de que una pantalla los dibuje. Angulo horizontal, aceleracion vertical.", "prompts": ["One dot per angle / Un punto por angulo", "Straight line or curve? / Recta o curva?", "Three points may not be enough to tell / Tres puntos quiza no alcanzan"], "grid": true, "xLabel": "angle / angulo (deg)", "yLabel": "acceleration / aceleracion (m/s2)", "sei": {"prompt_l1": {"es": "GRAFICA A MANO - pon tus tres puntos en los ejes antes de que una pantalla los dibuje. Angulo horizontal, aceleracion vertical."}, "labelBank": ["angle / angulo", "acceleration / aceleracion", "steeper / mas empinada", "bigger / mayor", "point / punto", "line / linea"], "modes": ["sketch"]}}, {"id": "w02d1-talk", "type": "callout", "variant": "note", "title": "Talk · Habla — 60 seconds each, then swap · 60 segundos cada uno, luego cambien", "markdown": "**Ask your partner · Pregúntale a tu pareja:** Your three points: a straight line, a curve, or you cannot tell from three? \"Cannot tell\" is allowed and it is the strongest answer. · Tus tres puntos: una recta, una curva, o no se puede saber con solo tres? \"No se puede saber\" vale, y es la respuesta mas fuerte.\n\nSpanish is allowed. The bridge student translates the physics, not the answer. · Se permite español. El «puente» traduce la física, no la respuesta."}, {"id": "w02d1-write", "type": "sentence_frame", "capture": true, "targetId": "pp.w02.a-vs-angle", "xp": 5, "frame": "When the angle went from ___ to ___ deg, the acceleration went from ___ to ___ m/s2, because ___.", "wordBank": ["angle / angulo", "steeper / mas empinada", "acceleration / aceleracion", "bigger / mayor", "smaller / menor", "because / porque"], "frames": [{"level": 1, "text": "Angle ___ to ___. Acceleration ___ to ___. [Bigger / smaller].", "text_l1": {"es": "Angulo ___ a ___. Aceleracion ___ a ___. [Mayor / menor]."}}, {"level": 2, "text": "When the angle got ___, the acceleration got ___ because ___.", "text_l1": {"es": "Cuando el angulo se hizo ___, la aceleracion se hizo ___ porque ___."}}, {"level": 3, "text": "Angle and acceleration: ___", "text_l1": {"es": "Angulo y aceleracion: ___"}}], "sei": {"prompt_l1": {"es": "ESCRIBE - que hizo el angulo"}, "talkFirst": true, "visual": {"src": "/images/sei/ramp-dilutes-g.svg", "alt": "A cart on a ramp: a red arrow g straight down, a shorter green arrow along the ramp. Steeper means closer to g."}, "modes": ["text"]}, "note": "WRITE - what the angle did"}, {"id": "w02d1-rate", "type": "self_assessment", "capture": true, "targetIds": ["pp.w02.a-vs-angle"], "note": "RATE YOURSELF · EVALÚATE — 1 Not yet · 2 Almost · 3 Got it, on each target you worked on today. Opens after the exit ticket on lobby days (MC-6)."}, {"id": "w02d2", "type": "callout", "variant": "tip", "title": "Day 2 · What would it read standing straight up? · Día 2 · Que marcaria de pie, vertical?", "markdown": "**HANDS · MANOS (25 min) — first, always.** You measure g yourselves. Photogate clamped VERTICAL, picket fence dropped through it by hand onto the cushion, three drops. Do not push it - drop it. Then the sim, to repeat it fast and clean. · Ustedes miden g. Fotopuerta VERTICAL, la barra de franjas cae por ella hasta el cojin, tres caidas. No la empujes - sueltala. Luego el sim, para repetirlo rapido y limpio.\n\nThen **RECORD · REGISTRA (30)** → **TALK · HABLA (25, pairs, either language · en parejas, en cualquier idioma)** → **WRITE · ESCRIBE (25, the frame below)**. Every segment ends with something saved here. · Cada segmento termina con algo guardado aquí."}, {"id": "w02d2-drop", "type": "data_table", "capture": true, "targetId": "pp.w02.g-diluted", "xp": 5, "columns": ["Drop / Caida", "g (m/s2)"], "rows": 3, "plot": false, "patternPrompt": "Are your three drops close to each other? What is your best value of g? · Tus tres caidas se parecen entre si? Cual es tu mejor valor de g?", "sei": {"prompt_l1": {"es": "Tus tres caidas se parecen entre si? Cual es tu mejor valor de g?"}, "talkFirst": false, "visual": {"src": "/images/sei/picket-fence-drop.svg", "alt": "A picket fence dropped through a vertical photogate onto a cushion, reading g of about 9.8."}, "modes": ["text"]}}, {"id": "w02d2-sim", "type": "sim_embed", "simulationSlug": "picket-fence-g"}, {"id": "w02d2-extrapolate", "type": "data_table", "capture": true, "targetId": "pp.w02.predict-fit", "xp": 5, "columns": ["Angle (deg) / Angulo", "Measured a (m/s2) / a medida", "Where MY line hits 90 deg / Donde MI linea llega a 90"], "rows": 3, "plot": false, "patternPrompt": "Extend your own line to 90 degrees and write the number. Do this BEFORE anyone says whether it is allowed. · Extiende tu propia linea hasta 90 grados y escribe el numero. Hazlo ANTES de que alguien diga si se vale.", "sei": {"prompt_l1": {"es": "Extiende tu propia linea hasta 90 grados y escribe el numero. Hazlo ANTES de que alguien diga si se vale."}, "talkFirst": false, "visual": {"src": "/images/sei/angle-vs-a-extended.svg", "alt": "Three measured points low on an angle-acceleration graph, a straight line through them extended to 90 degrees where it reaches about 14, above the dashed 9.8 line."}, "modes": ["text"]}}, {"id": "w02d2-beat", "type": "question", "capture": true, "targetId": "pp.w02.predict-fit", "xp": 5, "question": {"prompt": "Your extended line says the cart would accelerate at about 14 m/s2 standing straight up. The fence you dropped says 9.8. Can a cart on a ramp beat a rock falling straight down?", "options": [{"id": "no", "icon": "NO", "text": "No - so something is wrong with the LINE, not the measurement", "text_l1": {"es": "No - entonces algo esta mal con la LINEA, no con la medicion"}, "feedback": "Right. The measurement is real; the straight line was a guess that only fits where you measured. / Correcto. La medicion es real; la recta solo sirve donde mediste."}, {"id": "yes", "icon": "YES", "text": "Yes - the ramp helps it", "text_l1": {"es": "Si - la rampa lo ayuda"}, "feedback": "The ramp can only give the cart PART of gravity. It can never give more than all of it. / La rampa solo da PARTE de la gravedad. Nunca puede dar mas que toda."}, {"id": "meas", "icon": "X", "text": "No - so the measurement must be wrong", "text_l1": {"es": "No - entonces la medicion debe estar mal"}, "feedback": "You made that measurement with your own hands, three times. Trust it, and look again at the line. / Hiciste esa medicion con tus manos, tres veces. Confia en ella."}], "correctOptionId": "no", "explain": "Our line only works where we measured. Say that sentence out loud. · Nuestra linea solo sirve donde medimos. Di esa frase en voz alta."}, "sei": {"prompt_l1": {"es": "Tu linea extendida dice que el carrito aceleraria a unos 14 m/s2 vertical. La barra que soltaste dice 9.8. Puede un carrito en una rampa ganarle a una roca que cae?"}, "talkFirst": true, "frames": [{"level": 1, "text": "A cart [can / cannot] beat a falling rock. My line is [right / wrong] at 90.", "text_l1": {"es": "Un carrito [puede / no puede] ganarle a una roca que cae. Mi linea esta [bien / mal] en 90."}}, {"level": 2, "text": "The line cannot be trusted at 90 deg because ___.", "text_l1": {"es": "No se puede confiar en la linea en 90 grados porque ___."}}], "visual": {"src": "/images/sei/angle-vs-a-extended.svg", "alt": "Three measured points low on an angle-acceleration graph, a straight line through them extended to 90 degrees where it reaches about 14, above the dashed 9.8 line."}, "modes": ["choice"]}, "gate": true}, {"id": "w02d2-talk", "type": "callout", "variant": "note", "title": "Talk · Habla — 60 seconds each, then swap · 60 segundos cada uno, luego cambien", "markdown": "**Ask your partner · Pregúntale a tu pareja:** So what was wrong - the measurement, or the line? Say which, and say how you know. · Entonces que estaba mal - la medicion o la linea? Di cual, y di como lo sabes.\n\nSpanish is allowed. The bridge student translates the physics, not the answer. · Se permite español. El «puente» traduce la física, no la respuesta."}, {"id": "w02d2-write", "type": "sentence_frame", "capture": true, "targetId": "pp.w02.g-diluted", "xp": 5, "frame": "The ramp gives the cart ___ of gravity. Steeper means ___. Straight up would be ___.", "wordBank": ["part / parte", "all / toda", "closer to g / mas cerca de g", "bigger / mayor", "9.8", "steeper / mas empinada"], "frames": [{"level": 1, "text": "The ramp gives [part / all] of gravity. Steeper = [closer to g / further from g]. Straight up = [9.8].", "text_l1": {"es": "La rampa da [parte / toda] la gravedad. Mas empinada = [mas cerca de g / mas lejos de g]. Vertical = [9.8]."}}, {"level": 2, "text": "The ramp gives the cart ___ of gravity, so steeper means ___.", "text_l1": {"es": "La rampa le da al carrito ___ de la gravedad, asi que mas empinada significa ___."}}, {"level": 3, "text": "In my words: ___", "text_l1": {"es": "Con mis palabras: ___"}}], "sei": {"prompt_l1": {"es": "ESCRIBE - que le hace la rampa a la gravedad"}, "talkFirst": true, "visual": {"src": "/images/sei/ramp-dilutes-g.svg", "alt": "A cart on a ramp: a red arrow g straight down, a shorter green arrow along the ramp. Steeper means closer to g."}, "modes": ["text"]}, "note": "WRITE - what the ramp does to gravity"}, {"id": "w02d2-timeline", "type": "observation", "capture": true, "targetId": "pp.w00.timeline", "xp": 5, "patternPrompt": "TIMELINE ENTRY #4 · PLANNED — what did your team plan to do this block?", "interpretPrompt": "ACTUAL — what actually happened, and WHY the difference?", "patternFrame": "We planned ___. What actually happened: ___. The gap is because ___.", "comparatives": ["we planned · planeamos", "we actually · en realidad", "because · porque", "ran out of time · faltó tiempo", "it broke · se rompió", "it worked · funcionó"], "sei": {"prompt_l1": {"es": "ENTRADA #4 DE LA LÍNEA DE TIEMPO · PLANEADO — ¿qué planeó hacer tu equipo en este bloque? · REAL — ¿qué pasó de verdad, y POR QUÉ la diferencia?"}, "talkFirst": true, "frames": [{"level": 1, "text": "We planned ___. Actually ___.", "text_l1": {"es": "Planeamos ___. En realidad ___."}}, {"level": 2, "text": "We planned ___. Actually ___. The gap is because ___.", "text_l1": {"es": "Planeamos ___. En realidad ___. La diferencia es porque ___."}}, {"level": 3, "text": "Planned / actual / why: ___", "text_l1": {"es": "Planeado / real / por qué: ___"}}], "visual": {"src": "/images/sei/timeline-entry.svg", "alt": "A timeline card with three boxes: planned, actual, why the gap."}, "modes": ["text", "sketch"]}}, {"id": "w02d2-rate", "type": "self_assessment", "capture": true, "targetIds": ["pp.w02.g-diluted", "pp.w02.predict-fit", "pp.w00.timeline"], "note": "RATE YOURSELF · EVALÚATE — 1 Not yet · 2 Almost · 3 Got it, on each target you worked on today. Opens after the exit ticket on lobby days (MC-6)."}, {"id": "w02d3", "type": "callout", "variant": "tip", "title": "Day 3 · Off the end - run-out on the runner · Día 3 · Al salir - el recorrido en la alfombra", "markdown": "**HANDS · MANOS (25 min) — first, always.** Release and let it run until it stops, on the runner, three times at one angle. Nothing written for the first two - watch how much the three differ from each other. · Suelta y dejalo correr hasta parar, sobre la alfombra, tres veces en un angulo. No escribas en las dos primeras - mira cuanto se diferencian entre si.\n\nThen **RECORD · REGISTRA (30)** → **TALK · HABLA (25, pairs, either language · en parejas, en cualquier idioma)** → **WRITE · ESCRIBE (25, the frame below)**. Every segment ends with something saved here. · Cada segmento termina con algo guardado aquí."}, {"id": "w02d3-data", "type": "data_table", "capture": true, "targetId": "pp.w02.a-vs-angle", "xp": 5, "columns": ["Angle (deg) / Angulo", "Run 1 (cm)", "Run 2 (cm)", "Run 3 (cm)", "Average / Promedio", "Spread (biggest - smallest) / Diferencia"], "rows": 2, "plot": false, "patternPrompt": "How did doubling the steepness change the run-out? And how big is your spread compared to that change? · Como cambio el recorrido al duplicar la inclinacion? Y que tan grande es tu diferencia comparada con ese cambio?", "sei": {"prompt_l1": {"es": "Como cambio el recorrido al duplicar la inclinacion? Y que tan grande es tu diferencia comparada con ese cambio?"}, "talkFirst": false, "visual": {"src": "/images/sei/run-out-chain.svg", "alt": "Four boxes: angle, then acceleration, then speed at the bottom, then run-out. Friction acts at the last box."}, "modes": ["text"]}}, {"id": "w02d3-talk", "type": "callout", "variant": "note", "title": "Talk · Habla — 60 seconds each, then swap · 60 segundos cada uno, luego cambien", "markdown": "**Ask your partner · Pregúntale a tu pareja:** The cart left the ramp with a speed and the floor took it away. What would change the run-out WITHOUT changing the ramp at all? · El carrito salio de la rampa con una rapidez y el piso se la quito. Que cambiaria el recorrido SIN cambiar la rampa?\n\nSpanish is allowed. The bridge student translates the physics, not the answer. · Se permite español. El «puente» traduce la física, no la respuesta."}, {"id": "w02d3-claim", "type": "observation", "capture": true, "targetId": "pp.w02.friction-gap", "xp": 5, "patternPrompt": "RECORD - what happened to the run-out when the angle got steeper?", "interpretPrompt": "NAME IT - what is taking the speed away, and WHERE is it acting? Point to it on the chain.", "patternFrame": "The run-out got ___ because the cart left the ramp ___. The speed is taken away by ___ acting at ___.", "comparatives": ["run-out / recorrido", "faster / mas rapido", "friction / friccion", "floor / piso", "wheels / ruedas", "longer / mas largo"], "sei": {"prompt_l1": {"es": "REGISTRA - que paso con el recorrido cuando el angulo se hizo mas empinado? · NOMBRALO - que le quita la rapidez, y DONDE actua? Senalalo en la cadena."}, "talkFirst": true, "frames": [{"level": 1, "text": "Run-out got [longer / shorter]. Friction acts at the [floor / wheels].", "text_l1": {"es": "El recorrido fue [mas largo / mas corto]. La friccion actua en [el piso / las ruedas]."}}, {"level": 2, "text": "The run-out got ___ because the cart left the ramp ___, and ___ took the speed away.", "text_l1": {"es": "El recorrido fue ___ porque el carrito salio ___, y ___ le quito la rapidez."}}, {"level": 3, "text": "The chain, in my words: ___", "text_l1": {"es": "La cadena, con mis palabras: ___"}}], "visual": {"src": "/images/sei/run-out-chain.svg", "alt": "Four boxes: angle, then acceleration, then speed at the bottom, then run-out. Friction acts at the last box."}, "modes": ["text", "sketch"]}}, {"id": "w02d3-rate", "type": "self_assessment", "capture": true, "targetIds": ["pp.w02.a-vs-angle", "pp.w02.friction-gap"], "note": "RATE YOURSELF · EVALÚATE — 1 Not yet · 2 Almost · 3 Got it, on each target you worked on today. Opens after the exit ticket on lobby days (MC-6)."}, {"id": "w02d4", "type": "callout", "variant": "tip", "title": "Day 4 · The test - a new angle, locked · Día 4 · La prueba - un angulo nuevo, fijado", "markdown": "**HANDS · MANOS (15 min) — first, always.** HANDS FIRST, as always: one release at an angle you ALREADY ran on Wednesday, same runner, same release point. If it does not reproduce Wednesday, something moved - and we find out now, not after twenty predictions are locked against it. · PRIMERO LAS MANOS, como siempre: una suelta en un angulo que YA corriste el miercoles, misma alfombra, mismo punto de suelta. Si no reproduce el miercoles, algo se movio - y lo sabemos ahora, no despues de fijar veinte predicciones.\n\nThen **RECORD · REGISTRA (25)** → **TALK · HABLA (20, pairs, either language · en parejas, en cualquier idioma)** → **WRITE · ESCRIBE (20, the frame below)**. Every segment ends with something saved here. · Cada segmento termina con algo guardado aquí."}, {"id": "w02d4-anchor", "type": "data_table", "capture": true, "targetId": "pp.w02.predict-fit", "xp": 5, "columns": ["Known angle (deg) / Angulo conocido", "Today run-out (cm) / Hoy", "Wednesday (cm) / Miercoles", "Difference / Diferencia"], "rows": 1, "plot": false, "patternPrompt": "Does today match Wednesday? If not, what moved - the runner, the release point, or the cart? · Coincide hoy con el miercoles? Si no, que se movio - la alfombra, el punto de suelta, o el carrito?", "sei": {"prompt_l1": {"es": "Coincide hoy con el miercoles? Si no, que se movio - la alfombra, el punto de suelta, o el carrito?"}, "talkFirst": false, "visual": {"src": "/images/sei/run-out-chain.svg", "alt": "Four boxes: angle, then acceleration, then speed at the bottom, then run-out. Friction acts at the last box."}, "modes": ["text"]}}, {"id": "w02d4-predict", "type": "sentence_frame", "capture": true, "targetId": "pp.w02.predict-fit", "xp": 5, "frame": "I predict the run-out at ___ deg will be ___ cm, because on my graph ___. I would be wrong if ___.", "wordBank": ["my graph / mi grafica", "between / entre", "run-out / recorrido", "because / porque", "faster / mas rapido", "wrong if / equivocado si"], "frames": [{"level": 1, "text": "I predict ___ cm. From my graph: between ___ and ___.", "text_l1": {"es": "Predigo ___ cm. De mi grafica: entre ___ y ___."}}, {"level": 2, "text": "I predict ___ cm because on my graph ___.", "text_l1": {"es": "Predigo ___ cm porque en mi grafica ___."}}, {"level": 3, "text": "Prediction, reason, and what would prove me wrong: ___", "text_l1": {"es": "Prediccion, razon, y que demostraria que me equivoco: ___"}}], "sei": {"prompt_l1": {"es": "PREDICE (fijada) - el angulo NUEVO, antes de soltar"}, "talkFirst": true, "visual": {"src": "/images/sei/angle-vs-a-extended.svg", "alt": "Three measured points low on an angle-acceleration graph, a straight line through them extended to 90 degrees where it reaches about 14, above the dashed 9.8 line."}, "modes": ["text"]}, "note": "PREDICT (locked) - the NEW angle, before any release", "gate": true}, {"id": "w02d4-run", "type": "data_table", "capture": true, "targetId": "pp.w02.predict-fit", "xp": 5, "columns": ["Run / Corrida", "Run-out (cm) / Recorrido"], "rows": 3, "plot": false, "patternPrompt": "Three runs at the new angle. How much do they differ from each other? · Tres corridas en el angulo nuevo. Cuanto se diferencian entre si?", "sei": {"prompt_l1": {"es": "Tres corridas en el angulo nuevo. Cuanto se diferencian entre si?"}, "talkFirst": false, "modes": ["text"]}}, {"id": "w02d4-gap", "type": "data_table", "capture": true, "targetId": "pp.w02.friction-gap", "xp": 5, "columns": ["Predicted (cm) / Predicho", "Actual (cm) / Real", "Gap (cm) / Diferencia", "Bigger or smaller / Mayor o menor"], "rows": 1, "plot": false, "patternPrompt": "Numbers only for now. The explanation is Friday. · Solo numeros por ahora. La explicacion es el viernes.", "sei": {"prompt_l1": {"es": "Solo numeros por ahora. La explicacion es el viernes."}, "talkFirst": false, "visual": {"src": "/images/sei/run-out-chain.svg", "alt": "Four boxes: angle, then acceleration, then speed at the bottom, then run-out. Friction acts at the last box."}, "modes": ["text"]}}, {"id": "w02d4-talk", "type": "callout", "variant": "note", "title": "Talk · Habla — 60 seconds each, then swap · 60 segundos cada uno, luego cambien", "markdown": "**Ask your partner · Pregúntale a tu pareja:** Whose prediction was closest - and was it closest because of better reasoning, or a luckier angle? \"Luck\" is an honest answer. · Quien predijo mas cerca - y fue por mejor razonamiento o por un angulo con mas suerte? \"Suerte\" es una respuesta honesta.\n\nSpanish is allowed. The bridge student translates the physics, not the answer. · Se permite español. El «puente» traduce la física, no la respuesta."}, {"id": "w02d4-timeline", "type": "observation", "capture": true, "targetId": "pp.w00.timeline", "xp": 5, "patternPrompt": "TIMELINE ENTRY #5 · PLANNED — what did your team plan to do this block?", "interpretPrompt": "ACTUAL — what actually happened, and WHY the difference?", "patternFrame": "We planned ___. What actually happened: ___. The gap is because ___.", "comparatives": ["we planned · planeamos", "we actually · en realidad", "because · porque", "ran out of time · faltó tiempo", "it broke · se rompió", "it worked · funcionó"], "sei": {"prompt_l1": {"es": "ENTRADA #5 DE LA LÍNEA DE TIEMPO · PLANEADO — ¿qué planeó hacer tu equipo en este bloque? · REAL — ¿qué pasó de verdad, y POR QUÉ la diferencia?"}, "talkFirst": true, "frames": [{"level": 1, "text": "We planned ___. Actually ___.", "text_l1": {"es": "Planeamos ___. En realidad ___."}}, {"level": 2, "text": "We planned ___. Actually ___. The gap is because ___.", "text_l1": {"es": "Planeamos ___. En realidad ___. La diferencia es porque ___."}}, {"level": 3, "text": "Planned / actual / why: ___", "text_l1": {"es": "Planeado / real / por qué: ___"}}], "visual": {"src": "/images/sei/timeline-entry.svg", "alt": "A timeline card with three boxes: planned, actual, why the gap."}, "modes": ["text", "sketch"]}}, {"id": "w02d4-rate", "type": "self_assessment", "capture": true, "targetIds": ["pp.w02.predict-fit", "pp.w02.friction-gap", "pp.w00.timeline"], "note": "RATE YOURSELF · EVALÚATE — 1 Not yet · 2 Almost · 3 Got it, on each target you worked on today. Opens after the exit ticket on lobby days (MC-6)."}, {"id": "w02d5", "type": "callout", "variant": "tip", "title": "Day 5 · The reasoning artifact - name the friction · Día 5 · El artefacto de razonamiento - nombra la friccion", "markdown": "**HANDS · MANOS (20 min) — first, always.** One release at the tested angle, so the thing you are about to write about is in the room. Then the boards come down and the artifact opens. No new equipment today. · Una suelta en el angulo probado, para que lo que vas a escribir este en la sala. Luego se quitan los tableros y se abre el artefacto. Hoy no hay equipo nuevo.\n\nThen **RECORD · REGISTRA (35)** → **TALK · HABLA (25, pairs, either language · en parejas, en cualquier idioma)** → **WRITE · ESCRIBE (20, the frame below)**. Every segment ends with something saved here. · Cada segmento termina con algo guardado aquí."}, {"id": "w02d5-fig", "type": "figure", "src": "/images/sei/run-out-chain.svg", "align": "full", "alt": "Four boxes: angle, acceleration, speed at the bottom, run-out. Friction acts at the run-out box - the floor and the wheels.", "caption": "The chain / La cadena - angle to run-out, and where friction acts"}, {"id": "w02d5-artifact", "type": "observation", "capture": true, "targetId": "pp.w02.friction-gap", "xp": 5, "patternPrompt": "ARTIFACT - your prediction, the measurement, and the gap. Give all three as numbers.", "interpretPrompt": "EXPLAIN - name the friction AND say WHERE it acted: the runner, the wheels, the ramp, or the release. \"Friction\" with no place is not yet an explanation.", "patternFrame": "Predicted ___ cm, actual ___ cm. The gap is because friction acted at ___.", "comparatives": ["friction / friccion", "runner / alfombra", "wheels / ruedas", "ramp / rampa", "release / suelta", "gap / diferencia"], "sei": {"prompt_l1": {"es": "ARTEFACTO - tu prediccion, la medicion y la diferencia. Da los tres como numeros. · EXPLICA - nombra la friccion Y di DONDE actuo: la alfombra, las ruedas, la rampa o la suelta. \"Friccion\" sin lugar todavia no es una explicacion."}, "talkFirst": true, "frames": [{"level": 1, "text": "Predicted ___ cm. Actual ___ cm. [Bigger / smaller]. Friction acted at the [runner / wheels / ramp].", "text_l1": {"es": "Predicho ___ cm. Real ___ cm. [Mayor / menor]. La friccion actuo en [la alfombra / las ruedas / la rampa]."}}, {"level": 2, "text": "I predicted ___ cm and got ___ cm. The gap is because friction acted at ___.", "text_l1": {"es": "Predije ___ cm y obtuve ___ cm. La diferencia es porque la friccion actuo en ___."}}, {"level": 3, "text": "Prediction, result, and where the friction acted: ___", "text_l1": {"es": "Prediccion, resultado, y donde actuo la friccion: ___"}}], "visual": {"src": "/images/sei/run-out-chain.svg", "alt": "Four boxes: angle, then acceleration, then speed at the bottom, then run-out. Friction acts at the last box."}, "modes": ["text", "sketch"]}, "lobbyReady": true}, {"id": "w02d5-transfer", "type": "sentence_frame", "capture": true, "targetId": "pp.w02.g-diluted", "xp": 5, "frame": "At ___ degrees the run-out would be zero, because ___. That tells me the friction is ___.", "wordBank": ["zero / cero", "flat / plana", "does not move / no se mueve", "friction / friccion", "bigger / mayor", "smaller / menor"], "frames": [{"level": 1, "text": "Run-out is zero when the ramp is [flat / steep].", "text_l1": {"es": "El recorrido es cero cuando la rampa esta [plana / empinada]."}}, {"level": 2, "text": "At ___ deg the run-out would be zero because ___.", "text_l1": {"es": "En ___ grados el recorrido seria cero porque ___."}}, {"level": 3, "text": "Zero run-out, and what it says about friction: ___", "text_l1": {"es": "Recorrido cero, y que dice sobre la friccion: ___"}}], "sei": {"prompt_l1": {"es": "TRANSFERENCIA - el angulo que nunca probaste"}, "talkFirst": true, "visual": {"src": "/images/sei/ramp-dilutes-g.svg", "alt": "A cart on a ramp: a red arrow g straight down, a shorter green arrow along the ramp. Steeper means closer to g."}, "modes": ["text"]}, "note": "TRANSFER - the angle you never tested"}, {"id": "w02d5-talk", "type": "callout", "variant": "note", "title": "Talk · Habla — 60 seconds each, then swap · 60 segundos cada uno, luego cambien", "markdown": "**Ask your partner · Pregúntale a tu pareja:** Someone in your group named a DIFFERENT place for the friction than you did. Who is right, and what one measurement would settle it? · Alguien de tu grupo nombro un lugar DISTINTO para la friccion. Quien tiene razon, y que medicion lo resolveria?\n\nSpanish is allowed. The bridge student translates the physics, not the answer. · Se permite español. El «puente» traduce la física, no la respuesta."}, {"id": "w02-exit", "type": "exit_ticket", "capture": true, "targetId": "pp.w02.friction-gap", "xp": 5, "talkFirst": true, "prompt": "EXIT - Week 2 - one thing your prediction got wrong, and the one measurement that would have told you first.", "frame": "My prediction was wrong about ___. The measurement that would have told me is ___.", "sei": {"prompt_l1": {"es": "SALIDA - Semana 2 - una cosa en la que tu prediccion fallo, y la medicion que te lo habria dicho primero."}, "talkFirst": true, "frames": [{"level": 1, "text": "Wrong about: [the distance / the friction / the angle]. I would measure ___.", "text_l1": {"es": "Falle en: [la distancia / la friccion / el angulo]. Yo mediria ___."}}, {"level": 2, "text": "My prediction was wrong about ___ because ___. I would measure ___ first.", "text_l1": {"es": "Mi prediccion fallo en ___ porque ___. Yo mediria ___ primero."}}, {"level": 3, "text": "Wrong about ___ - would measure ___", "text_l1": {"es": "Falle en ___ - mediria ___"}}], "wordBank": ["predict / predecir", "measure / medir", "friction / friccion", "run-out / recorrido", "because / porque"], "visual": {"src": "/images/sei/run-out-chain.svg", "alt": "Four boxes: angle, then acceleration, then speed at the bottom, then run-out. Friction acts at the last box."}, "modes": ["text", "sketch"]}}, {"id": "w02d5-rate", "type": "self_assessment", "capture": true, "targetIds": ["pp.w02.friction-gap", "pp.w02.g-diluted"], "note": "RATE YOURSELF · EVALÚATE — 1 Not yet · 2 Almost · 3 Got it, on each target you worked on today. Opens after the exit ticket on lobby days (MC-6)."}]$$::jsonb), updated_at = now()
